<template>
  <span class="masterdata-tab-subheader">{{
    $t('response_from_endpoint') + ' (XML)'
  }}</span>
  <q-card flat bordered class="page-background">
    <q-card-section>
      <q-input
        v-model="endpoint_information['json_path']"
        outlined
        class="masterdata-json-path-input q-mb-md"
        :label="$t('json_path')"
        dense
      />
      <q-input
        v-model="formatted_response_textarea"
        borderless
        class="text-field-input"
        autogrow
        readonly
      />
    </q-card-section>
  </q-card>
</template>

<script>
import { defineComponent, ref } from 'vue';
import XmlBeautify from 'xml-beautify';
import { storeToRefs } from 'pinia';
import { useMasterDataLookupStore } from 'src/store/main';
export default defineComponent({
  // Your Vue component logic goes here
  name: 'xmlTablePath',
    props: {
    type: {
      type: String,
      default: 'record',
    },
  },
  mounted() {
    this.beautifyXML();
    // this.getDataBasePath()
  },
  methods: {
    checkIfDataHasHarray(key) {
      let array_key = '';
      const data = this.xml_json[key];
      Object.keys(data).forEach((current_key) => {
        const value = data[current_key];
         
        const is_array = Array.isArray(value);
        if (is_array) {
          array_key = current_key;
        }
      });
      return array_key;
    },
    getDataBasePath() {
      let test_key = '';
      Object.keys(this.xml_json).forEach((key) => {
        const value = this.xml_json[key];
         
        test_key = key;
      });
      const data_key = this.checkIfDataHasHarray(test_key);

      const data_base_path = test_key + '/' + data_key;

      if (this.type == 'record') {
        this.endpoint_information.json_path = data_base_path;
      } else if (this.type == 'template') {
        this.preset_information.json_path = data_base_path;
      }
    },
    beautifyXML() {
      let xml = this.response_textarea.replaceAll(/\\\"/g, '"');
      xml = xml.replace(/\\\"/g, '"');
      xml = xml.replace(/<\?xml.*\?>/g, '');
      xml = xml.replace(/^"/, '');
      xml = xml.replace(/"$/, '');
      var beautifiedXmlText = new XmlBeautify().beautify(xml, {
        indent: '     ', //indent pattern like white spaces
        useSelfClosingElement: true, //true:use self-closing element when empty element.
      });
      this.formatted_response_textarea = beautifiedXmlText;
    },
  },
  setup() {
    const master_data_store = useMasterDataLookupStore();
    const {
      create_parameters,
      custom_records,
      create_headers,
      xml_json,
      data_mode,
      raw_json_response,
      create_body,
      column_paths,
      auth_options,
      endpoint_information,
      preset_information,
      method_options,
      body_type_options,
      response_textarea,
      formatted_response_textarea,
      loading,
      custom_templates,
    } = storeToRefs(master_data_store);
    const {
      testEndpointResponse,
      formatJsonPath,
      createMasterData,
      resetAllFields,
      testDataExtraction,
      getMasterDataList,
    } = master_data_store;

    return {
      testEndpointResponse,
      formatJsonPath,
      createMasterData,
      resetAllFields,
      testDataExtraction,
      getMasterDataList,

      data_mode,
      xml_json,
      custom_records,
      raw_json_response,
      custom_templates,
      loading,
      create_parameters,
      create_headers,
      create_body,
      column_paths,
      auth_options,
      endpoint_information,
      preset_information,
      method_options,
      body_type_options,
      response_textarea,
      formatted_response_textarea,
    };
  },
});
</script>

