<template>
  <q-select
    v-model="selectedSubOrg"
    :options="subOrgOptions"
    outlined
    dense
    popup-content-class="dropdown-fit"
    :label="$t('select_sub_org')"
    @update:model-value="
      (val: any) => {
        selectSubOrg(val);
      }
    "
  >
    <template v-slot:option="scope">
      <q-item v-bind="scope.itemProps">
        <q-item-section>
          <q-item-label>{{ scope.opt.label }}</q-item-label>
          <q-tooltip>{{ scope.opt.label }}</q-tooltip>
        </q-item-section>
      </q-item>
    </template>
  </q-select>
</template>
<script lang="ts">
import { defineComponent, ref } from 'vue';
import { UserSubOrg } from 'src/utils/organization/index';
import { useMasterDataLookupStore } from 'src/store/main';

export default defineComponent({
  mounted() {
    this.getDropDownData();
  },
  methods: {
    selectSubOrg(val: any) {
      this.endpoint_information.sub_org_id = val.value;
    },
    selectDefault() {
      const sub_org_id = this.endpoint_information.sub_org_id;
      this.subOrgOptions.find((sub_org: any) => {
        if (sub_org.value === sub_org_id) {
          this.selectedSubOrg = sub_org;
          return true;
        }
        this.selectedSubOrg = this.subOrgOptions[0];
        return false;
      });
    },
    getDropDownData() {
      const sub_orgs = UserSubOrg.getSubOrgs();
      this.subOrgOptions.push({
        label: 'All',
        value: '',
      });
      sub_orgs.forEach((sub_org: any) => {
        this.subOrgOptions.push({
          label: sub_org.name,
          value: sub_org.id,
        });
      });
      this.selectDefault();
    },
  },
  name: 'subOrgSelect',
  setup() {
    const master_data_store = useMasterDataLookupStore();
    const { endpoint_information } = master_data_store;
    return {
      subOrgOptions: ref([] as any),
      selectedSubOrg: ref(''),
      modelValue: '',
      endpoint_information,
    };
  },
});
</script>
