<template>
  <span class="masterdata-tab-subheader">{{
    $t('select_table_columns')
  }}</span>
  <q-card flat bordered class="page-background">
    <q-card-section class="row">
      <q-input
        v-model="endpoint_information['column_name']"
        outlined
        class="masterdata-column-input"
        :label="$t('table_column_name')"
        dense
      />
      <q-select
        v-if="extracted_fields.length > 0"
        v-model="endpoint_information['column_value_name']"
        outlined
        multiple
        :options="extracted_fields"
        class="masterdata-column-input"
        :label="$t('column_value_name')"
        dense
      />
      <q-input
        v-else
        v-model="endpoint_information['column_value_name']"
        outlined
        class="masterdata-column-input"
        :label="$t('column_value_name')"
        dense
      />
      <f-btn
        :label="$t('add_new')"
        style="height: 40px"
        @click="addColumnToTable"
        :loading="loading"
        :loadinglabel="$t('loading')"
      />
      <f-btn
        :label="$t('test_extraction')"
        style="height: 40px"
        appearance="tertiary"
        class="q-ml-sm"
        @click="testExtraction"
        :loading="loading"
        :loadinglabel="$t('loading')"
      >
        <template v-slot:loading>
          <q-spinner-hourglass />
        </template>
      </f-btn>
      <subOrgSelect class="q-ml-sm min-width-140"></subOrgSelect>
    </q-card-section>
    <q-card-section class="row">
      <q-input
        v-model="formatted_response_textarea"
        borderless
        class="masterdata-create-table-original half-text-field-input"
        autogrow
        readonly
      />
      <div style="max-height: 25vh; overflow-y: auto; width: 50%">
        <DocBitsTable
          :rows="column_paths"
          :columns="xmlTableColumns"
          row-key="key"
          table-id="xml_table_creation_table"
          :features="{
            sorting: false,
            filtering: false,
            selection: false,
            bulkActions: false,
            rowActions: true,
            resizable: false,
            pagination: false,
            columnReorder: false,
            stickyLastColumn: true,
          }"
          :row-actions="xmlRowActions"
          no-data-label="no_record_found"
          flat-style
          @row-action="handleXmlRowAction"
        />
      </div>

      <q-input
        v-model="this.endpoint_information['validated_response_textarea']"
        borderless
        class="masterdata-create-table-original q-mt-md half-text-field-input"
        autogrow
        readonly
      />
    </q-card-section>
  </q-card>
</template>

<script>
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { ApiExceptions } from 'src/exceptions';
import subOrgSelect from 'src/pages/Settings/Components/MasterDataLookup/CustomMasterData/subOrgSelect.vue';
import { useMasterDataLookupStore } from 'src/store/main';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';
export default defineComponent({
  name: 'xmlTablePath',
    components: {
    subOrgSelect,
    DocBitsTable,
  },
  props: {
    type: {
      type: String,
      default: 'record',
    },
  },
  mounted() {
    this.getFieldsFromXmlJson();
  },
  methods: {
    removeColumnFromTable(index) {
      this.column_paths.splice(index, 1);
    },
    handleXmlRowAction(key, row) {
      if (key === 'delete') {
        const index = this.column_paths.findIndex((r) => r.key === row.key);
        if (index !== -1) this.removeColumnFromTable(index);
      }
    },
    async testExtraction() {
      try {
        this.loading = true;
        await this.testDataExtraction(this.type);
      } catch (e) {
        const message = ApiExceptions.getErrorMessage(e);
        this.loading = false;
        notify.error(message);
      } finally {
        this.loading = false;
      }
    },
    addColumnToTable() {
      try {
        if (this.column_paths.length === 0) {
          if (this.endpoint_information['column_name'].toLowerCase() != 'id') {
            notify.error(
              this.$t('column_id_required'),
            );
            return;
          }
        }
        let data_path = '';
        this.endpoint_information['column_value_name'].forEach(
          (value, index) => {
            if (
              this.endpoint_information['column_value_name'].length - 1 ===
              index
            ) {
              data_path += value;
            } else {
              data_path += value + ', ';
            }
          },
        );
        this.column_paths.push({
          key: this.endpoint_information['column_name'],
          value: data_path,
        });
        this.endpoint_information['column_name'] = '';
        this.endpoint_information['column_value_name'] = [];
      } catch (e) {
        const message = ApiExceptions.getErrorMessage(e);
        this.loading = false;
        notify.error(message);
      } finally {
        this.loading = false;
      }
    },
    getFieldsFromXmlJson() {
      const metadata_path = this.xml_json['miResult']['Metadata']['Field'];
      if (!metadata_path) {
        return;
      }
      metadata_path.forEach((field) => {
        this.extracted_fields.push(field['_attributes'].name);
      });
    },
  },
  setup() {
    const master_data_store = useMasterDataLookupStore();
    const {
      create_parameters,
      custom_records,
      create_headers,
      xml_json,
      data_mode,
      raw_json_response,
      create_body,
      column_paths,
      auth_options,
      endpoint_information,
      method_options,
      body_type_options,
      response_textarea,
      formatted_response_textarea,
      loading,
      custom_templates,
    } = storeToRefs(master_data_store);
    const {
      testEndpointResponse,
      formatJsonPath,
      createMasterData,
      resetAllFields,
      testDataExtraction,
      getMasterDataList,
    } = master_data_store;

    return {
      testEndpointResponse,
      formatJsonPath,
      createMasterData,
      resetAllFields,
      testDataExtraction,
      getMasterDataList,

      data_mode,
      xml_json,
      custom_records,
      raw_json_response,
      custom_templates,
      loading,
      create_parameters,
      create_headers,
      create_body,
      column_paths,
      auth_options,
      endpoint_information,
      method_options,
      body_type_options,
      response_textarea,
      formatted_response_textarea,

      extracted_fields: ref([]),
      xmlTableColumns: [
        { name: 'key', label: 'Key', field: 'key', align: 'left' },
        { name: 'value', label: 'Value', field: 'value', align: 'left' },
      ],
      xmlRowActions: [
        { key: 'delete', label: 'delete', icon: 'delete', color: 'negative' },
      ],
    };
  },
});
</script>
